# This file is generated by AI.

"""
构建 OpenWebGAL 脚本参考文档的结构化 JSON 数据.

功能:
    1. 从远程 GitHub 仓库或本地克隆的仓库中读取文档源文件.
    2. 将 arguments/ 下的片段内联到 commands/ 中的 @include 指令处.
    3. 解析 global.md 提取通用参数.
    4. 为每一条语句提取: 完整文档, 语句内容, 参数(含全局参数).
    5. 生成统一的 data/document.json, 供 Rust 编译期嵌入.

用法:
    使用远程仓库(默认):
        python scripts/update-document.py

    使用本地仓库:
        python scripts/update-document.py --local-path /path/to/WebGAL_Doc

输出:
    data/document.json
"""

import argparse
import json
import os
import re
import sys
from dataclasses import asdict, dataclass
from typing import Any, Dict, List, Tuple, TypedDict, cast

import requests

# --------------------------------------------------------------------------- #
# 配置常量
# --------------------------------------------------------------------------- #

REPO_OWNER = "OpenWebGAL"
REPO_NAME = "WebGAL_Doc"
BRANCH = "main"

BASE_PATH = "src/script-reference"
COMMANDS_DIR = f"{BASE_PATH}/commands"
ARGUMENTS_DIR = f"{BASE_PATH}/arguments"

DOCS_BASE_URL = "https://docs.openwebgal.com/script-reference"
DEFAULT_OUTPUT = os.path.join("data", "document.json")

HTTP_TIMEOUT = 30

# --------------------------------------------------------------------------- #
# GitHub API 响应类型
# --------------------------------------------------------------------------- #


class GitHubContentItem(TypedDict):
    """GitHub Contents API 返回的文件/目录项."""

    name: str
    path: str
    download_url: str | None
    type: str


# --------------------------------------------------------------------------- #
# 输出数据结构
# --------------------------------------------------------------------------- #


@dataclass
class DocumentField:
    """包含链接和文档内容的字段."""

    link: str
    document: str


@dataclass
class SentenceEntry:
    """一条完整语句的结构化信息.

    一条语句由语句类型 (command), 语句主参数 (content) 和语句参数 (arguments) 组成.
    """

    command: DocumentField
    content: DocumentField
    arguments: Dict[str, DocumentField]


# --------------------------------------------------------------------------- #
# 工具: 文件获取
# --------------------------------------------------------------------------- #


def fetch_github_directory(api_url: str) -> List[GitHubContentItem]:
    """通过 GitHub Contents API 获取目录下的文件列表."""
    headers = {"Accept": "application/vnd.github.v3+json"}
    try:
        resp = requests.get(api_url, headers=headers, timeout=HTTP_TIMEOUT)
        resp.raise_for_status()
        return cast(List[GitHubContentItem], resp.json())
    except requests.RequestException as e:
        print(f"❌ 无法获取 GitHub 目录 {api_url}: {e}")
        sys.exit(1)


def download_raw_content(download_url: str) -> str:
    """下载单个原始文本文件的内容(UTF-8)."""
    try:
        resp = requests.get(download_url, timeout=HTTP_TIMEOUT)
        resp.raise_for_status()
        return resp.text
    except requests.RequestException as e:
        print(f"❌ 无法下载文件 {download_url}: {e}")
        sys.exit(1)


def load_remote_files() -> Tuple[Dict[str, str], Dict[str, str]]:
    """从远程 GitHub 加载 arguments/ 和 commands/ 下的 .md 文件.

    Returns:
        (arguments, commands): 两个字典, 键为文件名(无扩展名), 值为文件内容.
    """
    print("🌐 从远程 GitHub 仓库加载文件...")

    args_api = (
        f"https://api.github.com/repos/{REPO_OWNER}/{REPO_NAME}"
        f"/contents/{ARGUMENTS_DIR}?ref={BRANCH}"
    )
    cmds_api = (
        f"https://api.github.com/repos/{REPO_OWNER}/{REPO_NAME}"
        f"/contents/{COMMANDS_DIR}?ref={BRANCH}"
    )

    args_files = fetch_github_directory(args_api)
    cmds_files = fetch_github_directory(cmds_api)

    args_md = [
        (f["name"], f["download_url"])
        for f in args_files
        if f["name"].endswith(".md") and f["download_url"] is not None
    ]
    cmds_md = [
        (f["name"], f["download_url"])
        for f in cmds_files
        if f["name"].endswith(".md") and f["download_url"] is not None
    ]

    arguments: Dict[str, str] = {}
    for name, url in args_md:
        key = os.path.splitext(name)[0]
        arguments[key] = download_raw_content(url)

    commands: Dict[str, str] = {}
    for name, url in cmds_md:
        key = os.path.splitext(name)[0]
        commands[key] = download_raw_content(url)

    print(f"  ✅ arguments: {len(arguments)} 个片段, commands: {len(commands)} 个文件")
    return arguments, commands


def load_local_files(local_root: str) -> Tuple[Dict[str, str], Dict[str, str]]:
    """从本地仓库加载 arguments/ 和 commands/ 下的 .md 文件.

    Args:
        local_root: 本地仓库根目录, 其下应有 src/script-reference/{arguments,commands}.

    Returns:
        (arguments, commands): 两个字典, 键为文件名(无扩展名), 值为文件内容.
    """
    print(f"📂 从本地仓库加载文件: {local_root}")

    args_dir = os.path.join(local_root, ARGUMENTS_DIR)
    cmds_dir = os.path.join(local_root, COMMANDS_DIR)

    if not os.path.isdir(args_dir):
        print(f"❌ 本地参数目录不存在: {args_dir}")
        sys.exit(1)
    if not os.path.isdir(cmds_dir):
        print(f"❌ 本地命令目录不存在: {cmds_dir}")
        sys.exit(1)

    def read_md_files(directory: str) -> Dict[str, str]:
        """读取目录下所有 .md 文件, 返回 {文件名(无扩展名): 内容}."""
        result: Dict[str, str] = {}
        for filename in os.listdir(directory):
            if filename.endswith(".md"):
                key = os.path.splitext(filename)[0]
                filepath = os.path.join(directory, filename)
                with open(filepath, "r", encoding="utf-8") as f:
                    result[key] = f.read()
        return result

    arguments = read_md_files(args_dir)
    commands = read_md_files(cmds_dir)
    print(f"  ✅ arguments: {len(arguments)} 个片段, commands: {len(commands)} 个文件")
    return arguments, commands


# --------------------------------------------------------------------------- #
# 预处理: @include 指令替换
# --------------------------------------------------------------------------- #


def resolve_includes(
    commands: Dict[str, str], arguments: Dict[str, str]
) -> Dict[str, str]:
    """将 commands 中的 @include 指令替换为 arguments 对应片段的内容.

    指令格式:
        <!-- @include: ../arguments/xxx.md -->
    """
    print("🔗 处理 @include 指令...")
    include_pattern = re.compile(r"<!--\s*@include:\s*\.\./arguments/(.+?)\.md\s*-->")

    resolved: Dict[str, str] = {}
    for cmd_name, content in commands.items():

        def replacer(match: re.Match[str]) -> str:
            arg_key = match.group(1)
            if arg_key in arguments:
                return arguments[arg_key]
            print(f"  ⚠️  未找到参数片段: {arg_key}, 保留原始指令.")
            return match.group(0)

        resolved[cmd_name] = include_pattern.sub(replacer, content)
    return resolved


# --------------------------------------------------------------------------- #
# Markdown 解析辅助
# --------------------------------------------------------------------------- #


def extract_section(markdown: str, heading: str, level: int = 2) -> str:
    """提取指定标题下的全部内容(不含标题行本身).

    从目标标题行的下一行开始, 直到下一个同级或更高级标题之前.
    若标题不存在, 返回空字符串.

    Args:
        markdown: 待解析的 Markdown 文本.
        heading: 要匹配的标题文本(不含开头的 # 和空格).
        level: 标题级别, 例如 level=2 表示查找 "## heading".

    Returns:
        提取出的内容字符串, 不含标题行本身.
    """
    heading_line = re.compile(
        rf"^{'#' * level}\s+{re.escape(heading)}\s*$", re.MULTILINE
    )
    any_heading = re.compile(r"^#{1," + str(level) + r"}\s+", re.MULTILINE)

    match = heading_line.search(markdown)
    if not match:
        return ""

    start = match.end()
    next_heading = any_heading.search(markdown, start)
    end = next_heading.start() if next_heading else len(markdown)
    return markdown[start:end].strip()


def extract_sub_sections(section_md: str, level: int = 3) -> Dict[str, str]:
    """从一段 Markdown 中提取所有指定级别的子章节.

    子章节内容从当前标题行开始, 到下一个同级或更高级标题结束(或文末).
    常用于提取 "## 参数" 下的 "### 参数名" 及其说明.

    Args:
        section_md: 包含子章节的 Markdown 文本.
        level: 子章节标题级别, 例如 level=3 表示 "### xxx".

    Returns:
        {子标题名: 完整子章节内容(含标题行)} 的字典.
    """
    subs: Dict[str, str] = {}
    heading_re = re.compile(rf"^{'#' * level}\s+(.+?)\s*$", re.MULTILINE)
    any_heading_re = re.compile(r"^#{1," + str(level) + r"}\s+", re.MULTILINE)

    for match in heading_re.finditer(section_md):
        param_name = match.group(1).strip()
        start = match.start()
        content_start = match.end()

        next_heading = any_heading_re.search(section_md, content_start)
        end = next_heading.start() if next_heading else len(section_md)

        full_content = section_md[start:end].strip()
        subs[param_name] = full_content
    return subs


# --------------------------------------------------------------------------- #
# 文档解析与结构化
# --------------------------------------------------------------------------- #


def parse_global_parameters(commands: Dict[str, str]) -> Dict[str, str]:
    """从 commands 中的 'global' 条目提取全局参数.

    检索 "## 参数" 章节, 提取其下的所有 "### 参数名" 子章节.

    Returns:
        {参数名: 参数文档(Markdown)} 的字典.
    """
    if "global" not in commands:
        print("ℹ️  未找到 global.md, 跳过全局参数.")
        return {}

    print("🌍 解析 global.md 中的通用参数...")
    global_md = commands["global"]
    param_section = extract_section(global_md, "参数", level=2)
    if not param_section:
        print("  ⚠️  未找到 '## 参数' 章节, 无全局参数.")
        return {}

    global_params = extract_sub_sections(param_section, level=3)
    print(f"  ✅ 找到 {len(global_params)} 个全局参数.")
    return global_params


def build_document_field(content: str, link: str) -> DocumentField:
    """根据内容和链接创建 DocumentField."""
    return DocumentField(link=link, document=content.strip())


def parse_sentence(
    stmt_name: str, full_md: str, global_params: Dict[str, str]
) -> SentenceEntry:
    """解析一个语句文档, 返回结构化的 SentenceEntry.

    从语句的 Markdown 中提取:
    - 完整文档 (command)
    - 语句内容章节 (content)
    - 参数集合 (arguments), 包含全局参数和语句自身参数.

    Args:
        stmt_name: 语句类型名称 (文件名无扩展名).
        full_md: 完整的 Markdown 内容 (已处理 include).
        global_params: 从 global.md 提取的全局参数映射.

    Returns:
        封装了 command, content, arguments 的 SentenceEntry 实例.
    """
    command_link = f"{DOCS_BASE_URL}/commands/{stmt_name}.html"
    command_field = build_document_field(full_md, command_link)

    content_md = extract_section(full_md, "语句内容", level=2)
    content_link = f"{command_link}#语句内容"
    content_field = build_document_field(content_md, content_link)

    param_section = extract_section(full_md, "参数", level=2)
    local_params: Dict[str, str] = {}
    if param_section:
        local_params = extract_sub_sections(param_section, level=3)

    arguments: Dict[str, DocumentField] = {}
    for p_name, p_doc in global_params.items():
        arg_link = f"{DOCS_BASE_URL}/commands/global.html#{p_name}"
        arguments[p_name] = build_document_field(p_doc, arg_link)
    for p_name, p_doc in local_params.items():
        arg_link = f"{command_link}#{p_name}"
        arguments[p_name] = build_document_field(p_doc, arg_link)

    return SentenceEntry(
        command=command_field,
        content=content_field,
        arguments=arguments,
    )


def build_output(
    commands: Dict[str, str], global_params: Dict[str, str]
) -> Dict[str, SentenceEntry]:
    """遍历所有语句文档 (排除 global), 构建最终的输出字典.

    Args:
        commands: 所有已处理 include 的命令/语句文档, 键为文件名(无扩展名).
        global_params: 全局参数映射.

    Returns:
        {语句类型名: SentenceEntry} 的字典.
    """
    print("📄 解析各语句文档...")
    output: Dict[str, SentenceEntry] = {}
    for stmt_name, full_md in commands.items():
        if stmt_name == "global":
            continue
        try:
            output[stmt_name] = parse_sentence(stmt_name, full_md, global_params)
        except Exception as e:
            print(f"  ❌ 解析 {stmt_name} 时出错: {e}")
    print(f"  ✅ 成功解析 {len(output)} 个语句.")
    return output


# --------------------------------------------------------------------------- #
# 序列化辅助
# --------------------------------------------------------------------------- #


def to_serializable(data: Dict[str, SentenceEntry]) -> Dict[str, Any]:
    """将 SentenceEntry 字典转换为可 JSON 序列化的纯字典."""
    return {k: asdict(v) for k, v in data.items()}


# --------------------------------------------------------------------------- #
# 主流程
# --------------------------------------------------------------------------- #


def main() -> None:
    parser = argparse.ArgumentParser(
        description="构建 OpenWebGAL 脚本参考文档的结构化 JSON 数据."
    )
    parser.add_argument(
        "--local-path",
        type=str,
        default=None,
        help="本地 WebGAL_Doc 仓库根目录路径 (若不提供则从远程 GitHub 拉取).",
    )
    parser.add_argument(
        "--output",
        type=str,
        default=DEFAULT_OUTPUT,
        help=f"输出 JSON 文件路径 (默认: {DEFAULT_OUTPUT}).",
    )
    args = parser.parse_args()

    if args.local_path:
        arguments, commands = load_local_files(args.local_path)
    else:
        arguments, commands = load_remote_files()

    commands = resolve_includes(commands, arguments)
    global_params = parse_global_parameters(commands)
    parsed_data = build_output(commands, global_params)

    output_path = args.output
    os.makedirs(os.path.dirname(output_path), exist_ok=True)
    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(to_serializable(parsed_data), f, ensure_ascii=False, indent=2)

    print(f"\n✅ 成功生成 {output_path}, 包含 {len(parsed_data)} 条语句.")


if __name__ == "__main__":
    main()
